package com.adria.transaction.service;
import com.adria.transaction.domain.BankTransaction;import com.adria.transaction.repository.TransactionRepository;import com.adria.transaction.client.AccountClient;import com.adria.transaction.messaging.*;import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Value;import org.springframework.transaction.annotation.Transactional;import io.github.resilience4j.circuitbreaker.annotation.CircuitBreaker;import java.util.*;import java.math.*;import java.time.*;
@Service public class TransactionService {private final TransactionRepository repo;private final AccountClient accounts;private final TransactionProducer producer;@Value("${bank.transaction.max-amount:1000}") private BigDecimal maxAmount;
 public TransactionService(TransactionRepository r,AccountClient a,TransactionProducer p){repo=r;accounts=a;producer=p;}public List<BankTransaction> all(){return repo.findAll();}public BankTransaction get(UUID id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Transaction introuvable"));}
 @CircuitBreaker(name="accountService",fallbackMethod="accountUnavailable") @Transactional public BankTransaction create(UUID accountId,BigDecimal amount,String currency,String category,String country){if(amount==null||amount.signum()<=0)throw new IllegalArgumentException("Le montant doit être positif");if(amount.compareTo(maxAmount)>0)throw new IllegalArgumentException("Plafond dépassé: "+maxAmount);Map<String,Object> a=accounts.getAccount(accountId);if(!"ACTIVE".equals(String.valueOf(a.get("status"))))throw new IllegalArgumentException("Compte bloqué");if(!currency.equals(String.valueOf(a.get("currency"))))throw new IllegalArgumentException("Devise différente de celle du compte");BigDecimal balance=new BigDecimal(String.valueOf(a.get("balance")));if(balance.compareTo(amount)<0)throw new IllegalArgumentException("Solde insuffisant");BankTransaction t=new BankTransaction();t.setAccountId(accountId);t.setAmount(amount);t.setCurrency(currency);t.setMerchantCategory(category);t.setCountry(country);t.setCreatedAt(Instant.now());BankTransaction saved=repo.save(t);accounts.updateBalance(accountId,balance.subtract(amount));producer.publish(new TransactionEvent(UUID.randomUUID(),"TransactionCreated",saved.getId(),accountId,amount,currency,saved.getCreatedAt()));return saved;}
 public BankTransaction accountUnavailable(UUID id,BigDecimal amount,String currency,String category,String country,Throwable ex){throw new IllegalStateException("Account-Service indisponible: opération refusée",ex);}
 @Transactional public Map<String,Object> transfer(UUID sourceId,UUID destinationId,BigDecimal amount){if(sourceId.equals(destinationId))throw new IllegalArgumentException("Les comptes doivent être différents");if(amount==null||amount.signum()<=0||amount.compareTo(maxAmount)>0)throw new IllegalArgumentException("Montant invalide ou plafond dépassé");Map<String,Object> src=accounts.getAccount(sourceId),dst=accounts.getAccount(destinationId);if(!"ACTIVE".equals(String.valueOf(src.get("status")))||!"ACTIVE".equals(String.valueOf(dst.get("status"))))throw new IllegalArgumentException("Compte bloqué");if(!Objects.equals(src.get("currency"),dst.get("currency")))throw new IllegalArgumentException("Devises différentes");BigDecimal sb=new BigDecimal(String.valueOf(src.get("balance"))),db=new BigDecimal(String.valueOf(dst.get("balance")));if(sb.compareTo(amount)<0)throw new IllegalArgumentException("Solde insuffisant");accounts.updateBalance(sourceId,sb.subtract(amount));accounts.updateBalance(destinationId,db.add(amount));return Map.of("status","TRANSFERRED","sourceAccountId",sourceId,"destinationAccountId",destinationId,"amount",amount);}
}
